<?php get_header(); $paged = max(1, get_query_var('paged')); $posts_query = new WP_Query(['post_type' => 'post', 'post_status' => 'publish', 'paged' => $paged, 'posts_per_page' => 9]); ?><main class="oubei-section"><div class="oubei-container"><p class="eyebrow">Insights</p><h1>Engineering notes and sourcing guidance.</h1><div class="oubei-card-grid oubei-card-grid--catalog"><?php if ($posts_query->have_posts()) : while ($posts_query->have_posts()) : $posts_query->the_post(); get_template_part('template-parts/post-card'); endwhile; wp_reset_postdata(); else : ?><p>No articles published yet.</p><?php endif; ?></div><?php echo wp_kses_post(paginate_links(['total' => $posts_query->max_num_pages, 'current' => $paged])); ?></div></main><?php get_footer();
